-- 20261022090000 套用後唯讀檢查：每列都應為 true（只讀，不寫入）
SELECT '3 支新函式都存在' AS item, to_regprocedure('public.wizard_save_basic_info(uuid, text, text, text, text)') IS NOT NULL AND to_regprocedure('public.wizard_precheck_redact(jsonb)') IS NOT NULL AND to_regprocedure('public.wizard_basic_info_errors(text, text, text, text)') IS NOT NULL AS ok
UNION ALL SELECT 'save_basic_info、precheck_redact 為 SECURITY DEFINER', (SELECT bool_and(p.prosecdef) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname IN ('wizard_save_basic_info', 'wizard_precheck_redact'))
UNION ALL SELECT 'save_basic_info：authenticated 可、anon 不可', has_function_privilege('authenticated', 'public.wizard_save_basic_info(uuid, text, text, text, text)', 'EXECUTE') AND NOT has_function_privilege('anon', 'public.wizard_save_basic_info(uuid, text, text, text, text)', 'EXECUTE')
UNION ALL SELECT 'precheck_redact：authenticated 不可', NOT has_function_privilege('authenticated', 'public.wizard_precheck_redact(jsonb)', 'EXECUTE')
UNION ALL SELECT 'wizard_precheck_core：已移除 OTA 紅黃檢查、改回 ota_status、flags 有 hq_detail', position('needs_ack' IN replace(pg_get_functiondef('public.wizard_precheck_core(uuid)'::regprocedure), E'\r', '')) = 0 AND position('ota_mapping' IN replace(pg_get_functiondef('public.wizard_precheck_core(uuid)'::regprocedure), E'\r', '')) = 0 AND position('ota_status' IN replace(pg_get_functiondef('public.wizard_precheck_core(uuid)'::regprocedure), E'\r', '')) > 0 AND position('hq_detail' IN replace(pg_get_functiondef('public.wizard_precheck_core(uuid)'::regprocedure), E'\r', '')) > 0
UNION ALL SELECT 'wizard_precheck_core：basic_info 改用 wizard_basic_info_errors', position('wizard_basic_info_errors' IN replace(pg_get_functiondef('public.wizard_precheck_core(uuid)'::regprocedure), E'\r', '')) > 0
UNION ALL SELECT 'wizard_submit 簽名不變、不再檢查 OTA 勾選、回傳經 redact', to_regprocedure('public.wizard_submit(uuid, boolean)') IS NOT NULL AND position('p_ota_ack IS NOT TRUE' IN replace(pg_get_functiondef('public.wizard_submit(uuid, boolean)'::regprocedure), E'\r', '')) = 0 AND position('wizard_precheck_redact' IN replace(pg_get_functiondef('public.wizard_submit(uuid, boolean)'::regprocedure), E'\r', '')) > 0
UNION ALL SELECT 'wizard_precheck 回傳經 redact', position('wizard_precheck_redact' IN replace(pg_get_functiondef('public.wizard_precheck(uuid)'::regprocedure), E'\r', '')) > 0
UNION ALL SELECT '開賣守門仍呼叫 wizard_precheck_core（M3 未變）', position('wizard_precheck_core' IN replace(pg_get_functiondef('public.accommodation_info_guard_is_active()'::regprocedure), E'\r', '')) > 0
UNION ALL SELECT '規則抽查：合法資料 0 個錯誤、全空 4 個錯誤', cardinality(public.wizard_basic_info_errors('礁溪山嵐', '宜蘭縣礁溪鄉溫泉路 1 號', '03-987-6543', repeat('好', 30))) = 0 AND cardinality(public.wizard_basic_info_errors('', '', '', '')) = 4;
